#[test]
fn cargo_target_arguments_preserve_library_binary_and_integration_semantics() {
    let targets = [
        target_identity("lib", "fixture"),
        target_identity("bin", "fixture"),
        target_identity("test", "resident"),
    ];

    let arguments = targets
        .iter()
        .map(target_arguments)
        .collect::<Result<Vec<_>, _>>()
        .expect("current target kinds map to Cargo selectors")
        .concat();

    assert_eq!(
        arguments,
        ["--lib", "--bin", "fixture", "--test", "resident"]
            .map(OsString::from)
            .to_vec()
    );
}

#[test]
fn successful_prebuild_repairs_a_missing_cargo_bin_exe_publication() {
    let root = fixture_root("workspace-stale-binary-repair");
    let programs = root.join("programs");
    let target = root.join("target");
    let deps = target.join("debug/deps");
    let fingerprints = target.join("debug/.fingerprint/fixture");
    fs::create_dir_all(&programs).expect("repair program directory creates");
    fs::create_dir_all(&deps).expect("stale test output directory creates");
    fs::create_dir_all(&fingerprints).expect("stale fingerprint directory creates");
    let stale_test = executable(&deps, "resident-deadbeef", "#!/bin/sh\nexit 0\n");
    let fingerprint = fingerprints.join("test-integration-test-resident");
    fs::write(&fingerprint, "fresh\n").expect("stale fingerprint writes");
    let published = executable(&target.join("debug"), "fixture-tool", "#!/bin/sh\nexit 0\n");
    fs::remove_file(&published).expect("published binary is removed after prebuild state exists");
    let cargo = executable(
        &programs,
        "cargo",
        concat!(
            "#!/bin/sh\n",
            "printf '%s\\n' \"$*\" >> \"$FIXTURE_ROOT/commands.log\"\n",
            "if [ \"$1\" = build ]; then\n",
            "  /bin/mkdir -p \"$CARGO_TARGET_DIR/debug\"\n",
            "  printf '#!/bin/sh\\nexit 0\\n' > \"$CARGO_TARGET_DIR/debug/fixture-tool\"\n",
            "  /bin/chmod 755 \"$CARGO_TARGET_DIR/debug/fixture-tool\"\n",
            "fi\n",
        ),
    );
    let environment = binary_output_environment(&root, &programs);
    let inventory = binary_output_inventory(&root);
    let mut output = Vec::new();

    prebuild_all_tests(
        &root,
        &environment,
        cargo.as_os_str(),
        &inventory,
        &mut output,
    )
    .expect("canonical no-run prebuild repairs its missing binary publication");
    prebuild_all_tests(
        &root,
        &environment,
        cargo.as_os_str(),
        &inventory,
        &mut output,
    )
    .expect("warm canonical prebuild reuses the repaired binary publication");

    assert!(executable_file(&published));
    assert!(
        stale_test.is_file(),
        "the fresh test binary remains reusable"
    );
    assert_eq!(
        fs::read_to_string(fingerprint).expect("fingerprint remains readable"),
        "fresh\n"
    );
    assert_eq!(
        fs::read_to_string(root.join("commands.log"))
            .expect("repair commands read")
            .lines()
            .collect::<Vec<_>>(),
        [
            "test --locked --workspace --all-targets --no-run",
            "build --locked --package fixture-id --bin fixture-tool",
            "test --locked --workspace --all-targets --no-run",
        ]
    );
    fs::remove_dir_all(root).expect("stale binary repair fixture removes");
}

#[test]
fn prebuild_rejects_a_repair_that_does_not_publish_the_owned_binary() {
    let root = fixture_root("workspace-missing-binary-refusal");
    let programs = root.join("programs");
    fs::create_dir_all(&programs).expect("refusal program directory creates");
    let cargo = executable(&programs, "cargo", "#!/bin/sh\nexit 0\n");
    let environment = binary_output_environment(&root, &programs);
    let inventory = binary_output_inventory(&root);
    let expected = root.join("target/debug/fixture-tool");
    let mut output = Vec::new();

    let error = prebuild_all_tests(
        &root,
        &environment,
        cargo.as_os_str(),
        &inventory,
        &mut output,
    )
    .expect_err("a successful Cargo status cannot replace the missing output postcondition")
    .to_string();

    assert!(error.contains(&expected.display().to_string()), "{error}");
    assert!(error.contains("package \"fixture\""), "{error}");
    assert!(error.contains("binary target \"fixture-tool\""), "{error}");
    fs::remove_dir_all(root).expect("missing binary refusal fixture removes");
}

#[test]
fn prebuilt_execution_refuses_a_missing_cargo_bin_exe_before_any_shard_starts() {
    let root = fixture_root("workspace-prebuilt-binary-guard");
    let programs = root.join("programs");
    fs::create_dir_all(root.join("src")).expect("prebuilt guard source directory creates");
    fs::create_dir_all(&programs).expect("prebuilt guard program directory creates");
    fs::write(root.join("Cargo.toml"), "[workspace]\n").expect("prebuilt guard manifest writes");
    fs::write(root.join("src/main.rs"), "fn main() {}\n")
        .expect("prebuilt guard binary source writes");
    let metadata = serde_json::json!({
        "packages": [{
            "id": "fixture-id",
            "name": "fixture",
            "manifest_path": root.join("Cargo.toml"),
            "targets": [{
                "name": "fixture-tool",
                "kind": ["bin"],
                "test": true,
                "src_path": root.join("src/main.rs"),
            }],
        }],
        "workspace_members": ["fixture-id"],
        "target_directory": root.join("target"),
        "build_directory": root.join("target/cargo-build"),
    });
    fs::write(
        root.join("metadata.json"),
        serde_json::to_vec(&metadata).expect("prebuilt guard metadata encodes"),
    )
    .expect("prebuilt guard metadata writes");
    executable(
        &programs,
        "cargo",
        concat!(
            "#!/bin/sh\n",
            "printf '%s\\n' \"$1\" >> \"$FIXTURE_ROOT/commands.log\"\n",
            "if [ \"$1\" = metadata ]; then\n",
            "  /bin/cat \"$FIXTURE_ROOT/metadata.json\"\n",
            "  exit 0\n",
            "fi\n",
            "printf 'unexpected shard launch\\n' >&2\n",
            "exit 70\n",
        ),
    );
    let mut entries = binary_output_environment(&root, &programs)
        .entries()
        .iter()
        .cloned()
        .collect::<BTreeMap<_, _>>();
    entries.insert(OsString::from(SHARED_OUTPUTS_ENV), OsString::from("1"));
    let environment = Environment::new(entries).expect("prebuilt guard environment admits");
    let expected = root.join("target/debug/fixture-tool");
    let mut output = Vec::new();

    let error = run_prebuilt_shared_at(&root, environment, 1, &mut output)
        .expect_err("prebuilt runner rejects its missing binary publication")
        .to_string();

    assert!(error.contains(&expected.display().to_string()), "{error}");
    assert!(error.contains("package \"fixture\""), "{error}");
    assert!(error.contains("binary target \"fixture-tool\""), "{error}");
    assert_eq!(
        fs::read_to_string(root.join("commands.log"))
            .expect("prebuilt guard commands read")
            .lines()
            .collect::<Vec<_>>(),
        ["metadata"],
        "binary validation refuses before Cargo receives a shard command"
    );
    assert!(!String::from_utf8_lossy(&output).contains("stage=start"));
    fs::remove_dir_all(root).expect("prebuilt binary guard fixture removes");
}

#[test]
fn metadata_inventory_refuses_a_target_without_readable_source_weight() {
    let root = fixture_root("workspace-missing-target-source");
    fs::create_dir_all(&root).expect("missing-source fixture root creates");
    fs::write(root.join("Cargo.toml"), "[workspace]\n")
        .expect("missing-source manifest fixture writes");
    let root = fs::canonicalize(root).expect("missing-source fixture root canonicalizes");
    let missing = root.join("tests/missing.rs");

    let error = inventory_from_metadata(
        Metadata {
            workspace_members: vec!["fixture-id".to_owned()],
            target_directory: root.join("target"),
            build_directory: root.join("target/cargo-build"),
            packages: vec![MetadataPackage {
                id: "fixture-id".to_owned(),
                name: "fixture".to_owned(),
                manifest_path: root.join("Cargo.toml"),
                dependencies: Vec::new(),
                features: BTreeMap::new(),
                targets: vec![MetadataTarget {
                    name: "missing".to_owned(),
                    kind: vec!["test".to_owned()],
                    test: true,
                    src_path: missing.clone(),
                    required_features: Vec::new(),
                }],
            }],
        },
        &root,
    )
    .expect_err("missing target source refuses inventory")
    .to_string();

    assert!(error.contains(&missing.display().to_string()), "{error}");
    assert!(error.contains("metadata failed"), "{error}");
    fs::remove_dir_all(root).expect("missing-source fixture removes");
}

#[test]
fn successful_execution_publishes_one_exact_target_inventory_without_parsing_logs() {
    let execution = WorkspaceTestExecution::from_inventory(&fixture_inventory());
    assert_eq!(
        execution.tests(),
        ["fixture-a::lib:fixture-a", "fixture-b::bin:fixture-b"]
    );

    let source = wire::Digest::compute(wire::Domain::GateTree, b"workspace tests");
    let unknown = execution
        .publish_unknown(
            source,
            vec!["src/lib.rs".to_owned()],
            "coverage publisher emitted no complete receipt",
        )
        .expect("unknown coverage remains typed");
    assert_eq!(unknown.tests_run().len(), 2);
    assert!(unknown.test_coverage().is_empty());
    assert!(matches!(
        unknown.coverage(),
        crate::CoverageCompleteness::Unknown { .. }
    ));
}

#[test]
#[expect(
    clippy::disallowed_methods,
    reason = "the end-to-end canonical runner fixture captures its test process environment"
)]
fn selected_workspace_runner_executes_the_reported_target_from_changed_rust_source() {
    let root = fixture_root("workspace-selected-test");
    fs::create_dir_all(root.join("src")).expect("create selected workspace fixture");
    fs::create_dir_all(root.join("tests")).expect("create selected integration fixture");
    fs::write(
        root.join("Cargo.toml"),
        concat!(
            "[package]\n",
            "name = \"selected-fixture\"\n",
            "version = \"0.0.0\"\n",
            "edition = \"2024\"\n",
        ),
    )
    .expect("write selected fixture manifest");
    fs::write(
        root.join("Cargo.lock"),
        concat!(
            "# This file is automatically @generated by Cargo.\n",
            "# It is not intended for manual editing.\n",
            "version = 4\n\n",
            "[[package]]\n",
            "name = \"selected-fixture\"\n",
            "version = \"0.0.0\"\n",
        ),
    )
    .expect("write selected fixture lock");
    fs::write(
        root.join("src/lib.rs"),
        "pub fn selected() -> bool { true }\n",
    )
    .expect("write selected fixture source");
    fs::write(
        root.join("tests/gate_cli.rs"),
        concat!(
            "#[test]\n",
            "fn configured_dispatch_does_not_leak_into_gate_cli() {\n",
            "    assert!(std::env::var_os(\"SPICE_RS_PRE_COMMIT_SOURCE\").is_none());\n",
            "    assert_eq!(std::env::var(\"PASSTHROUGH\").as_deref(), Ok(\"retained\"));\n",
            "    assert_eq!(std::env::var(\"RUSTC_WRAPPER\").as_deref(), Ok(\"\"));\n",
            "}\n",
        ),
    )
    .expect("write selected gate_cli fixture");
    // This test itself runs inside Cargo. A selected workspace-test parent also
    // supplies its output roots, so inheriting them here would make the nested
    // Cargo wait on the parent test binary's own build-directory lock.
    let mut entries = std::env::vars_os()
        .filter(|(name, _)| {
            name != OsStr::new(CARGO_TARGET_DIR) && name != OsStr::new(CARGO_BUILD_BUILD_DIR)
        })
        .collect::<BTreeMap<_, _>>();
    entries.insert(
        OsString::from(PRE_COMMIT_SOURCE),
        OsString::from("configured-source"),
    );
    entries.insert(OsString::from("PASSTHROUGH"), OsString::from("retained"));
    entries.insert(
        OsString::from(RUSTC_WRAPPER),
        OsString::from("/ambient/sccache"),
    );
    let environment = Environment::new(entries).expect("capture isolated test environment");
    let mut output = Vec::new();

    let report = run_selected_at(
        WorkspaceTestRoots::new(&root, &root),
        wire::Digest::compute(wire::Domain::GateTree, b"selected fixture"),
        &["tests/gate_cli.rs".to_owned()],
        environment,
        1,
        &mut output,
    )
    .unwrap_or_else(|error| {
        panic!(
            "selected runner failed: {error}; output={}",
            String::from_utf8_lossy(&output)
        )
    });

    assert!(report.admits());
    assert_eq!(report.tests(), ["selected-fixture::test:gate_cli"]);
    assert!(
        String::from_utf8(output)
            .unwrap()
            .contains("[rust-test-selection] detail=canonical-report sources=1 tests=1 edges=1")
    );
    fs::remove_dir_all(root).expect("remove selected workspace fixture");
}

