fn materialized_fixture_inventory(label: &str) -> (PathBuf, Inventory) {
    let root = fixture_root(label);
    fs::create_dir_all(root.join("fixture-a/src")).expect("create fixture-a source directory");
    fs::create_dir_all(root.join("fixture-b/src")).expect("create fixture-b source directory");
    fs::write(root.join("fixture-a/src/lib.rs"), "pub fn fixture_a() {}\n")
        .expect("write fixture-a library");
    fs::write(root.join("fixture-b/src/main.rs"), "fn main() {}\n")
        .expect("write fixture-b binary");
    let root = fs::canonicalize(root).expect("canonical materialized fixture root");
    let mut inventory = fixture_inventory();
    inventory.target_directory = root.join("target");
    inventory.build_directory = root.join("target/cargo-build");
    for package in &mut inventory.packages {
        package.root = relocate_fixture_path(&package.root, &root);
        for dependency in &mut package.dependencies {
            *dependency = relocate_fixture_path(dependency, &root);
        }
        for target in &mut package.declared_targets {
            target.source = relocate_fixture_path(&target.source, &root);
            for declared in &mut target.declared_path_sources {
                declared.path = relocate_fixture_path(&declared.path, &root);
            }
        }
        for target in &mut package.targets {
            target.source = relocate_fixture_path(&target.source, &root);
            for declared in &mut target.declared_path_sources {
                declared.path = relocate_fixture_path(&declared.path, &root);
            }
        }
    }
    (root, inventory)
}

fn relocate_fixture_path(path: &Path, root: &Path) -> PathBuf {
    root.join(
        path.strip_prefix("/workspace")
            .expect("fixture inventory path starts at /workspace"),
    )
}

fn binary_output_inventory(root: &Path) -> Inventory {
    Inventory {
        packages: Vec::new(),
        binary_outputs: vec![BinaryOutput {
            package_id: "fixture-id".to_owned(),
            package_name: "fixture".to_owned(),
            target_name: "fixture-tool".to_owned(),
        }],
        target_directory: root.join("target"),
        build_directory: root.join("target/cargo-build"),
    }
}

fn binary_output_environment(root: &Path, programs: &Path) -> Environment {
    Environment::new([
        (OsString::from("FIXTURE_ROOT"), root.as_os_str().to_owned()),
        (
            OsString::from(CARGO_TARGET_DIR),
            root.join("target").into_os_string(),
        ),
        (
            OsString::from(CARGO_BUILD_BUILD_DIR),
            root.join("target/cargo-build").into_os_string(),
        ),
        (
            OsString::from("PATH"),
            env::join_paths([programs, Path::new("/usr/bin"), Path::new("/bin")])
                .expect("binary output fixture PATH composes"),
        ),
    ])
    .expect("binary output fixture environment admits")
}

fn target(root: &Path, name: &str, kind: &[&str], test: bool) -> MetadataTarget {
    let source = match kind.first().copied() {
        Some("lib") => root.join("src/lib.rs"),
        Some("bin") => root.join("src/main.rs"),
        Some("custom-build") => root.join("build.rs"),
        _ => root.join(format!("tests/{name}.rs")),
    };
    MetadataTarget {
        name: name.to_owned(),
        kind: kind.iter().map(|kind| (*kind).to_owned()).collect(),
        test,
        src_path: source,
        required_features: Vec::new(),
    }
}

fn target_identity(kind: &str, name: &str) -> TargetIdentity {
    TargetIdentity {
        package: "fixture-id".to_owned(),
        kind: kind.to_owned(),
        name: name.to_owned(),
        required_features: Vec::new(),
        source: PathBuf::from(format!("/workspace/{kind}/{name}.rs")),
        declared_path_sources: Vec::new(),
        source_bytes: 1,
    }
}

fn fixture_root(name: &str) -> PathBuf {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    env::temp_dir().join(format!(
        "spice-{name}-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ))
}

fn configured_dispatch_boundary_fixture(root: &Path) -> (PathBuf, PathBuf) {
    let programs = root.join("programs");
    fs::create_dir_all(root.join("src")).expect("create Cargo-boundary fixture source");
    fs::create_dir_all(root.join("tests")).expect("create Cargo-boundary integration tests");
    fs::create_dir_all(&programs).expect("create Cargo-boundary program directory");
    fs::write(root.join("Cargo.toml"), CONFIGURED_BOUNDARY_MANIFEST)
        .expect("write Cargo-boundary fixture manifest");
    fs::write(root.join("Cargo.lock"), CONFIGURED_BOUNDARY_LOCK)
        .expect("write Cargo-boundary fixture lock");
    fs::write(
        root.join("src/lib.rs"),
        "pub fn admitted() -> bool { true }\n",
    )
    .expect("write Cargo-boundary fixture library");
    fs::write(root.join("tests/gate_cli.rs"), CONFIGURED_BOUNDARY_TEST)
        .expect("write Cargo-boundary integration test");
    let log = root.join("cargo-boundaries.log");
    executable(
        &programs,
        "cargo",
        &format!(
            concat!(
                "#!/bin/sh\n",
                "[ -z \"$RUSTC_WRAPPER\" ] || exit 49\n",
                "printf '%s|%s|%s|%s\\n' \"$1\" ",
                "\"${{SPICE_RS_PRE_COMMIT_SOURCE-unset}}\" ",
                "\"${{PASSTHROUGH-unset}}\" ",
                "\"${{SPICE_RS_PRE_COMMIT_PATHS-unset}}\" >> \"$BOUNDARY_LOG\"\n",
                "exec \"{}\" \"$@\"\n",
            ),
            env!("CARGO"),
        ),
    );
    (programs, log)
}

#[expect(
    clippy::disallowed_methods,
    reason = "the end-to-end Cargo-boundary fixture captures its process environment"
)]
fn configured_dispatch_boundary_environment(programs: PathBuf, log: &Path) -> Environment {
    let cargo_directory = Path::new(env!("CARGO"))
        .parent()
        .expect("Cargo executable has a parent")
        .to_path_buf();
    let path = env::join_paths([
        programs,
        cargo_directory,
        PathBuf::from("/usr/bin"),
        PathBuf::from("/bin"),
    ])
    .expect("compose Cargo-boundary fixture PATH");
    let mut entries = std::env::vars_os()
        .filter(|(name, _)| {
            name != OsStr::new(CARGO_TARGET_DIR) && name != OsStr::new(CARGO_BUILD_BUILD_DIR)
        })
        .collect::<BTreeMap<_, _>>();
    entries.insert(OsString::from("PATH"), path);
    entries.insert(OsString::from("BOUNDARY_LOG"), log.as_os_str().to_owned());
    entries.insert(
        OsString::from(PRE_COMMIT_SOURCE),
        OsString::from("configured-source"),
    );
    entries.insert(OsString::from("PASSTHROUGH"), OsString::from("retained"));
    entries.insert(
        OsString::from(RUSTC_WRAPPER),
        OsString::from("/ambient/sccache"),
    );
    entries.insert(
        OsString::from("SPICE_RS_PRE_COMMIT_PATHS"), // env-policy: allow
        OsString::from("[\"tests/gate_cli.rs\"]"),
    );
    entries.insert(OsString::from(SHARED_OUTPUTS_ENV), OsString::from("1"));
    Environment::new(entries).expect("capture Cargo-boundary environment")
}

fn assert_configured_dispatch_boundaries(log: &Path) {
    let boundaries = fs::read_to_string(log).expect("read observed Cargo boundaries");
    let commands = boundaries
        .lines()
        .map(|line| {
            let fields = line.split('|').collect::<Vec<_>>();
            assert_eq!(
                fields,
                [fields[0], "unset", "retained", "[\"tests/gate_cli.rs\"]",],
                "Cargo child inherited the wrong authority: {line}"
            );
            fields[0]
        })
        .collect::<Vec<_>>();
    assert_eq!(
        commands,
        ["metadata", "test", "test"],
        "the fixture must observe metadata, prebuild, and shard Cargo boundaries"
    );
}

fn executable(root: &Path, name: &str, body: &str) -> PathBuf {
    let path = root.join(name);
    fs::write(&path, body).expect("fixture executable writes");
    let mut permissions = fs::metadata(&path)
        .expect("fixture executable metadata reads")
        .permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&path, permissions).expect("fixture executable becomes executable");
    path
}

fn read_pid(path: &Path) -> u32 {
    fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("fixture pid {} reads: {error}", path.display()))
        .trim()
        .parse()
        .expect("fixture pid parses")
}

fn assert_process_terminal(pid: u32, role: &str) {
    let started = Instant::now();
    while process_live(pid) && started.elapsed() < Duration::from_secs(2) {
        thread::sleep(Duration::from_millis(20));
    }
    assert!(!process_live(pid), "{role} process {pid} survived timeout");
}

fn process_live(pid: u32) -> bool {
    let output = Command::new("/bin/ps")
        .args(["-p", &pid.to_string(), "-o", "stat="])
        .output()
        .expect("process state probe launches");
    output.status.success()
        && String::from_utf8_lossy(&output.stdout)
            .trim()
            .chars()
            .next()
            .is_some_and(|state| state != 'Z')
}
